"    const targetPrinters = billPrinterConfig.names && billPrinterConfig.names.length > 0
      ? billPrinterConfig.names
      : [billPrinterConfig.name || posSettings.printerName || 'Default'];

    if (window.require) {
      try {
        const { ipcRenderer } = window.require('electron');
        copiesToPrint.forEach(copyLabel => {
          const labelHtml = copyLabel
            ? `<div class="center bold copy-label" style="font-size: 11px; margin-top: 1mm; border: 1px dashed #000; padding: 0.5mm 0;">${copyLabel}</div>`
            : '';
          const finalReceiptHtml = receiptHtml
            .replace('__COPY_LABEL_PLACEHOLDER__', labelHtml)
            .replace('<script>window.onload = () => { window.print(); window.close(); }</script>', '');

          targetPrinters.forEach(pName => {
            ipcRenderer.send('print-silent', {
              html: finalReceiptHtml,
              printerName: pName
            });
          });
        });
        return;
      } catch (err) {
        console.error("Silent print failed:", err);
      }
    }

    copiesToPrint.forEach(copyLabel => {
      const labelHtml = copyLabel
        ? `<div class="center bold copy-label" style="font-size: 11px; margin-top: 1mm; border: 1px dashed #000; padding: 0.5mm 0;">${copyLabel}</div>`
        : '';
      const finalReceiptHtml = receiptHtml.replace('__COPY_LABEL_PLACEHOLDER__', labelHtml);
      const printWindow = window.open('', '_blank', 'width=300,height=600');
      if (printWindow) {
        printWindow.document.write(finalReceiptHtml);
        printWindow.document.close();
      }
    });
  };"

